import asyncio, json
from playwright.async_api import async_playwright
URL='file:///home/claude/shots/app.html'
R=[]
def ok(n,c,x=''): R.append(c); print('PASS' if c else 'FAIL', n, x, flush=True)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); ctx = await b.new_context(viewport={'width':1440,'height':900})
        pg = await ctx.new_page(); errs=[]
        pg.on('pageerror', lambda e: errs.append(str(e)+' '+str(getattr(e,'stack',''))[:300]))
        await pg.goto(URL); await pg.wait_for_selector('#main .page'); await pg.wait_for_timeout(600)
        E=pg.evaluate
        async def go(h): await E(f"location.hash={json.dumps(h)}"); await pg.wait_for_timeout(500)
        # sidebar + theme
        bg = await E("getComputedStyle(document.querySelector('.side')).backgroundImage")
        ok('sidebar uses petrol gradient', 'rgb(11, 63, 56)' in bg, bg[:80])
        ok('theme toggle sits in top bar', await E("!!document.querySelector('#topbar [data-themetoggle]') && !document.querySelector('.side [data-themetoggle]')"))
        await pg.click('#topbar [data-themetoggle]'); await pg.wait_for_timeout(500)
        ok('dark applied', await E("document.documentElement.dataset.theme") == 'dark')
        await pg.reload(); await pg.wait_for_selector('#main .page'); await pg.wait_for_timeout(500)
        ok('theme persists after reload', await E("document.documentElement.dataset.theme") == 'dark')
        await pg.click('#topbar [data-themetoggle]'); await pg.wait_for_timeout(300)
        # dashboard structure
        await go('#/dashboard?v=alt'); await pg.wait_for_timeout(1500)
        ok('KPI row with 5 tiles', await E("document.querySelectorAll('.dz-kpis .dz-kpi').length") == 5)
        nd_all = await E("visiblePartnerships().filter(p=>!p.isDraft).length")
        ok('status legend sums to all records', await E("[...document.querySelectorAll('.dz-st b')].reduce((t,b)=>t+ +b.textContent,0)") == nd_all)
        ok('all panels render', await E("['.dz3-comp','.hz','.dz-acts','.dz-line','.dz-funnel','.tm','.dz-exp','.dz-fields','.dz-trend','.dz2-owners','.dz3-deep'].every(s=>document.querySelector(s))"))
        act_ui = int(await E("document.querySelector('.dz-kpi .cu').dataset.v"))
        act_calc = await E("visiblePartnerships().filter(p=>!p.isDraft && ['active','soon'].includes(pStatus(p))).length")
        ok('active KPI matches records', act_ui == act_calc, (act_ui, act_calc))
        ok('trend "now" matches KPI', int((await E("document.querySelector('.dzl-val').textContent")).strip()) == act_calc and int(await E("document.querySelector('.dz-trend b').dataset.v")) == act_calc)
        narr = await pg.inner_text('.dz-summary')
        ok('narrative mentions totals', 'تضم المحفظة' in narr and 'سارية' in narr)
        ok('no coloured edge lines on cards', await E("[...document.querySelectorAll('.dz-act,.dz-kpi,.dp')].every(e=>{const c=getComputedStyle(e); return c.borderRightWidth==='0px'||c.borderRightColor===c.borderLeftColor}) && getComputedStyle(document.querySelector('.dz-kpi'),'::before').content==='none'"))
        ok('dashboard is light in light mode', await E("getComputedStyle(document.querySelector('.dz-kpi')).backgroundColor") == 'rgb(255, 255, 255)')
        await pg.click('[data-present]'); await pg.wait_for_timeout(600)
        w = await E("[innerWidth, Math.round(document.querySelector('.main').getBoundingClientRect().width), Math.round(document.querySelector('.dz3').getBoundingClientRect().width)]")
        ok('presentation mode uses full width', w[1] == w[0] and w[2] > w[0] * 0.9, w)
        ok('exit button visible in presentation', await E("getComputedStyle(document.querySelector('.present-exit')).display !== 'none'"))
        await pg.click('[data-present-exit]'); await pg.wait_for_timeout(300)
        ok('exit button leaves presentation', await E("!document.querySelector('.app').classList.contains('present')"))
        await pg.click('#topbar [data-themetoggle]'); await pg.wait_for_timeout(900)
        ok('dashboard is dark in dark mode', await E("getComputedStyle(document.querySelector('.dz-kpi')).backgroundColor") != 'rgb(255, 255, 255)')
        await pg.click('#topbar [data-themetoggle]'); await pg.wait_for_timeout(700)
        # tooltip
        await pg.locator('.ev-hit').nth(5).hover(); await pg.wait_for_timeout(250)
        ok('chart tooltip shows', await E("document.querySelector('#tip').classList.contains('on') && document.querySelector('#tip').textContent.includes('شراكات سارية')"))
        # filter
        await pg.click('#dashF .fbtn[data-dim="sector"]'); await pg.click('#dashF .fpop .fo:has-text("خاص") input'); await pg.click('#dashF [data-done]'); await pg.wait_for_timeout(500)
        narr2 = await pg.inner_text('.dz-summary')
        ok('filters re-compute narrative', 'ضمن الفلاتر المختارة' in narr2)
        nd = await E("applyFilters(visiblePartnerships(), App.dashF).filter(p=>!p.isDraft).length")
        ok('filtered roadmap rows ≤ filtered records', await E("document.querySelectorAll('.rm-row:not(.rm-head)').length") <= nd)
        await E("App.dashF={}"); await go('#/'); await go('#/dashboard?v=alt'); await pg.wait_for_timeout(1300)
        # bar drill
        bar = pg.locator('.dz-bars').first.locator('.dzb-r').first
        v = int((await bar.locator('b').inner_text()).strip())
        await bar.click(); await pg.wait_for_timeout(900)
        ok('bar click cross-filters the whole dashboard', bool(await E("App.dashF.sector && App.dashF.sector.length===1")), await E("JSON.stringify(App.dashF)"))
        ok('scope equals bar value', int(await E("document.querySelector('.dz2-scope b').textContent")) == v)
        ok('KPIs recomputed for the filter', int(await E("document.querySelector('.dz2-kpi .cu').dataset.v")) == await E("applyFilters(visiblePartnerships(),App.dashF).filter(p=>!p.isDraft&&['active','soon'].includes(pStatus(p))).length"))
        ok('active filter chip shown', await E("document.querySelectorAll('.dz2-chip').length") == 1)
        st = pg.locator('.dz-st').first; sv = int((await st.locator('b').inner_text()).strip())
        await st.click(); await pg.wait_for_timeout(900)
        ok('second chart click combines filters', await E("Object.keys(App.dashF).length") == 2 and int(await E("document.querySelector('.dz2-scope b').textContent")) == sv)
        await pg.click('[data-undo]'); await pg.wait_for_timeout(800)
        ok('undo restores previous filter', await E("Object.keys(App.dashF).join()") == 'sector')
        await pg.click('[data-reset]'); await pg.wait_for_timeout(800)
        ok('reset clears all filters', await E("Object.keys(App.dashF).length") == 0 and await E("document.querySelectorAll('.dz2-chip').length") == 0)
        # count-up: transitions from previous value and never jitters width
        await pg.click('.dz2-legend .dz-st >> nth=0'); await pg.wait_for_timeout(60)
        mid = await E("document.querySelector('.dz2-kpi .cu').textContent")
        await pg.wait_for_timeout(1000)
        fin = await E("document.querySelector('.dz2-kpi .cu').textContent")
        ok('filter change animates to new value', fin == await E("document.querySelector('.dz2-kpi .cu').dataset.v") and await E("document.querySelector('.dz2-kpi .cu').style.minWidth") != '')
        await pg.click('[data-reset]'); await pg.wait_for_timeout(900)
        await pg.click('.dz2-kpi[data-drawer="soon"]'); await pg.wait_for_timeout(500)
        ok('KPI click opens details panel with matching records', await E("document.querySelectorAll('#dzDrawer .dz2-dr-it').length") == await E("visiblePartnerships().filter(p=>!p.isDraft&&pStatus(p)==='soon').length"))
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(400)
        ok('Esc closes details panel', await E("!document.querySelector('#dzDrawer')"))
        # images
        await go('#/'); await pg.wait_for_timeout(500)
        ok('hero uses image', await E("!!document.querySelector('.hero-art img.photo[src^=\"data:image\"]')"))
        n = await E("fieldPhotos().length")
        await pg.click('.mosaic .mt >> nth=0'); await pg.wait_for_timeout(500)
        ok('mosaic opens gallery with all photos', await E("document.querySelectorAll('.gal-thumbs button').length") == n, n)
        await pg.keyboard.press('ArrowLeft'); await pg.wait_for_timeout(200)
        ok('arrow moves to next', (await pg.inner_text('.gal-count')).startswith('2 من'))
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(200)
        ok('escape closes gallery', await E("!document.querySelector('.lightbox')"))
        ok('mosaic has unique images', await E("new Set(fieldPhotos().map(x=>x.fileId)).size === fieldPhotos().length"))
        # library picker in form
        rid = await E("D.partnerships.find(p=>!p.demo && p.title.includes('عيني')).id")
        await go(f'#/partnerships/{rid}/edit'); await pg.click('[data-step="admin"]'); await pg.click('[data-libcover]'); await pg.wait_for_timeout(300)
        await pg.click('.libgrid [data-lk="mangrove"]'); await pg.wait_for_timeout(300)
        await pg.click('[data-save="final"]'); await pg.wait_for_timeout(600)
        ok('cover chosen from library saved', await E(f"D.partnerships.find(p=>p.id==='{rid}').coverFileId") == 'lib:mangrove')
        ok('detail shows illustrative caption', await E("!!document.querySelector('.dhead .illus')"))
        # download library image as attachment
        async with pg.expect_download() as dl:
            pid = await E("D.partnerships.find(p=>p.attachments.some(a=>a.fileId.startsWith('lib:'))).id")
            await go(f'#/partnerships/{pid}'); await pg.click('#files [data-dl] >> nth=0')
        d = await dl.value; ok('library image downloadable', (await d.path()) is not None)
        # migration from saved v1 data
        await E("""(async()=>{ D.settings.schema=1; D.settings.home.sections=D.settings.home.sections.filter(s=>s.id!=='gallery'); D.settings.home.heroImageFileId=null; D.partnerships.forEach(p=>{p.coverFileId=null; p.attachments=(p.attachments||[]).filter(a=>!a.fileId.startsWith('lib:'))}); D.achievements.forEach(a=>{a.coverFileId=null;a.gallery=[]}); await Repo.saveSettings(); await Store.putMany('partnerships',D.partnerships); await Store.putMany('achievements',D.achievements); })()""")
        await pg.reload(); await pg.wait_for_selector('#main .page'); await pg.wait_for_timeout(700)
        ok('migration adds gallery section', await E("D.settings.home.sections.some(s=>s.id==='gallery') && D.settings.schema===5"))
        ok('migration assigns covers + galleries', await E("D.partnerships.filter(p=>p.coverFileId).length >= 10 && D.partnerships.some(p=>p.attachments.some(a=>a.fileId.startsWith('lib:')))"))
        # print
        await go('#/dashboard?v=alt'); await pg.wait_for_timeout(1300)
        await E("window.print=()=>{}; 0"); await pg.click('.dashpage [data-print]'); await pg.wait_for_timeout(900)
        await pg.emulate_media(media='print')
        ok('print: dedicated sheet with title, date, scope and filters; app chrome hidden', await E("!!document.querySelector('#printSheet .ps-head h1') && document.querySelector('#printSheet .ps-meta').innerText.includes('النطاق') && document.querySelector('#printSheet .ps-meta').innerText.includes('آخر تحديث') && getComputedStyle(document.querySelector('#app')).display==='none'"))
        ok('print uses the same dashboard design (horizon, strip, panels)', await E("!!document.querySelector('#printSheet .dz3-hero .hz') && document.querySelectorAll('#printSheet .dz3-ledger .dz3-cell').length===5 && !!document.querySelector('#printSheet .dz3-comp') && !document.querySelector('#printSheet .ps-donut, #printSheet .ps-gauge')"))
        ok('printed figures equal screen figures', await E("[...document.querySelectorAll('#printSheet .dz3-ledger .cu')].map(x=>x.dataset.v).join()===[...document.querySelectorAll('#dashBody .dz3-ledger .cu')].map(x=>x.dataset.v).join()"))
        ok('print: no animation residue (final values)', await E("[...document.querySelectorAll('.cu')].every(x=>x.textContent===cuFmt(+x.dataset.v||0,x.dataset.fmt))"))
        await pg.pdf(path='/home/claude/shots/j/dash-v2.pdf', prefer_css_page_size=True, print_background=True)
        import subprocess; info = subprocess.run(['pdfinfo','/home/claude/shots/j/dash-v2.pdf'],capture_output=True,text=True).stdout
        pages = int([l for l in info.splitlines() if l.startswith('Pages')][0].split()[-1])
        ok('print: one A3 landscape page, nothing cut', pages == 1 and 'A3' in info, pages)
        await E("window.dispatchEvent(new Event('afterprint'))")
        await pg.emulate_media(media='screen')
        # mobile overflow
        m = await b.new_context(viewport={'width':390,'height':844}, is_mobile=True, has_touch=True); mp = await m.new_page()
        await mp.goto(URL+'#/dashboard?v=alt'); await mp.wait_for_selector('#main .page'); await mp.wait_for_timeout(1500)
        ok('mobile dashboard no horizontal overflow', await mp.evaluate("document.documentElement.scrollWidth <= innerWidth + 1"), await mp.evaluate("[document.documentElement.scrollWidth, innerWidth]"))
        await mp.screenshot(path='/home/claude/shots/m-dash.png', full_page=True)
        ok('no page errors', not errs, errs[:3])
        await b.close()
    print('SUMMARY', sum(R), '/', len(R))
asyncio.run(main())
